 try{if(Number(request.headers.get('content-length')||0)>4000)return json({error:'Request too large'},413);const text=await request.text();if(text.length>4000)return json({error:'Request too large'},413);const body=JSON.parse(text);if(typeof body.url!=='string')return json({error:'Property URL required'},400);const property=await importPublicListing(body.url);return json({property})}catch(e){return json({error:e.message||'Import unavailable'},422)}
